"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[16722],{12924(e,a,o){o.r(a),o.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>r,metadata:()=>s,toc:()=>l});const s=JSON.parse('{"id":"cursos/arquitectura-software/modulos/fundamentos-arquitectura/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 son las Architecture Fitness Functions y c\xf3mo difieren de las t\xe1cticas arquitect\xf3nicas tradicionales?","source":"@site/docs/cursos/arquitectura-software/modulos/01-fundamentos-arquitectura/cuestionario.md","sourceDirName":"cursos/arquitectura-software/modulos/01-fundamentos-arquitectura","slug":"/cursos/arquitectura-software/modulos/fundamentos-arquitectura/cuestionario","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/fundamentos-arquitectura/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/fundamentos-arquitectura/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/arquitectura-software/modulos/fundamentos-arquitectura/ejercicio"}}');var i=o(74848),n=o(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},t=void 0,c={},l=[{value:"2. [Investigar] \xbfQu\xe9 son las Architecture Fitness Functions y c\xf3mo difieren de las t\xe1cticas arquitect\xf3nicas tradicionales?",id:"2-investigar-qu\xe9-son-las-architecture-fitness-functions-y-c\xf3mo-difieren-de-las-t\xe1cticas-arquitect\xf3nicas-tradicionales",level:3},{value:"3. [Investigar] \xbfC\xf3mo impacta Team Topologies (Matthew Skelton y Manuel Pais) en la arquitectura de software m\xe1s all\xe1 de la Ley de Conway?",id:"3-investigar-c\xf3mo-impacta-team-topologies-matthew-skelton-y-manuel-pais-en-la-arquitectura-de-software-m\xe1s-all\xe1-de-la-ley-de-conway",level:3},{value:"4. [Investigar] \xbfQu\xe9 propone Gregor Hohpe con la met\xe1fora del &quot;Architect Elevator&quot; y c\xf3mo cambia la forma de comunicar decisiones arquitect\xf3nicas a stakeholders?",id:"4-investigar-qu\xe9-propone-gregor-hohpe-con-la-met\xe1fora-del-architect-elevator-y-c\xf3mo-cambia-la-forma-de-comunicar-decisiones-arquitect\xf3nicas-a-stakeholders",level:3},{value:"5. [Conectar] La clase menciona que los ADRs documentan decisiones arquitect\xf3nicas. \xbfC\xf3mo se relaciona esto con el proceso de RFC (Request for Comments) que usan empresas como Spotify y c\xf3mo ambos se complementan?",id:"5-conectar-la-clase-menciona-que-los-adrs-documentan-decisiones-arquitect\xf3nicas-c\xf3mo-se-relaciona-esto-con-el-proceso-de-rfc-request-for-comments-que-usan-empresas-como-spotify-y-c\xf3mo-ambos-se-complementan",level:3},{value:"6. [Conectar] La clase cubre los 6 atributos de calidad principales. \xbfC\xf3mo los ampl\xeda y estructura el est\xe1ndar ISO/IEC 25010:2023 respecto a lo visto?",id:"6-conectar-la-clase-cubre-los-6-atributos-de-calidad-principales-c\xf3mo-los-ampl\xeda-y-estructura-el-est\xe1ndar-isoiec-250102023-respecto-a-lo-visto",level:3},{value:"7. [Conectar] En clase vimos que &quot;toda decisi\xf3n implica un trade-off&quot;. \xbfC\xf3mo ayuda el modelo Cynefin (Dave Snowden) a tomar decisiones arquitect\xf3nicas en diferentes contextos de complejidad?",id:"7-conectar-en-clase-vimos-que-toda-decisi\xf3n-implica-un-trade-off-c\xf3mo-ayuda-el-modelo-cynefin-dave-snowden-a-tomar-decisiones-arquitect\xf3nicas-en-diferentes-contextos-de-complejidad",level:3},{value:"8. [Cuestionar] \xbfEs el rol del arquitecto de software obsoleto en equipos verdaderamente \xe1giles y aut\xf3nomos? Contrast\xe1 la postura de Martin Fowler con la de Mary Poppendieck.",id:"8-cuestionar-es-el-rol-del-arquitecto-de-software-obsoleto-en-equipos-verdaderamente-\xe1giles-y-aut\xf3nomos-contrast\xe1-la-postura-de-martin-fowler-con-la-de-mary-poppendieck",level:3},{value:"9. [Cuestionar] \xbfEl principio de la &quot;Revisarltima Decisi\xf3n Responsable&quot; (Last Responsible Moment) es peligroso en sistemas cr\xedticos de seguridad (avi\xf3nica, dispositivos m\xe9dicos)? Contrast\xe1 con la postura de Nancy Leveson.",id:"9-cuestionar-el-principio-de-la-revisarltima-decisi\xf3n-responsable-last-responsible-moment-es-peligroso-en-sistemas-cr\xedticos-de-seguridad-avi\xf3nica-dispositivos-m\xe9dicos-contrast\xe1-con-la-postura-de-nancy-leveson",level:3},{value:"10. [Cuestionar] \xbfDeber\xedan los atributos de calidad ser definidos &quot;top-down&quot; por el arquitecto o emerger de los equipos? \xbfQu\xe9 dice el manifiesto \xe1gil y c\xf3mo lo rebate el SEI?",id:"10-cuestionar-deber\xedan-los-atributos-de-calidad-ser-definidos-top-down-por-el-arquitecto-o-emerger-de-los-equipos-qu\xe9-dice-el-manifiesto-\xe1gil-y-c\xf3mo-lo-rebate-el-sei",level:3}];function d(e){const a={em:"em",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,n.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.h3,{id:"2-investigar-qu\xe9-son-las-architecture-fitness-functions-y-c\xf3mo-difieren-de-las-t\xe1cticas-arquitect\xf3nicas-tradicionales",children:"2. [Investigar] \xbfQu\xe9 son las Architecture Fitness Functions y c\xf3mo difieren de las t\xe1cticas arquitect\xf3nicas tradicionales?"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),": Las Architecture Fitness Functions, introducidas por Neal Ford, Rebecca Parsons y Patrick Kua en ",(0,i.jsx)(a.em,{children:"Building Evolutionary Architectures"})," (2017), son pruebas automatizadas que verifican que la arquitectura cumple sus atributos de calidad en cada cambio. A diferencia de las t\xe1cticas arquitect\xf3nicas tradicionales (que son decisiones de dise\xf1o puntuales), las fitness functions son ",(0,i.jsx)(a.strong,{children:"ejecutables y continuas"}),": se integran en el pipeline de CI/CD y fallan el build si se detecta una violaci\xf3n arquitect\xf3nica. Ejemplos: ArchUnit verificando que no haya dependencias circulares entre paquetes, tests de performance que fallan si la latencia p95 supera 200ms, o verificadores de convenciones de nombres."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),': El concepto de "arquitectura evolutiva" de Ford et al. sostiene que en entornos \xe1giles, la arquitectura debe poder evolucionar guiada por constraints automatizados, no por revisiones manuales. Mientras las t\xe1cticas del SEI son prescriptivas ("us\xe1 heartbeat para disponibilidad"), las fitness functions son verificables y continuas, cerrando el loop de feedback arquitect\xf3nico. Esto extiende lo visto en clase sobre testabilidad y calidad: no basta con dise\xf1ar para un QA, hay que verificarlo autom\xe1ticamente en cada commit.']}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"3-investigar-c\xf3mo-impacta-team-topologies-matthew-skelton-y-manuel-pais-en-la-arquitectura-de-software-m\xe1s-all\xe1-de-la-ley-de-conway",children:"3. [Investigar] \xbfC\xf3mo impacta Team Topologies (Matthew Skelton y Manuel Pais) en la arquitectura de software m\xe1s all\xe1 de la Ley de Conway?"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": Skelton y Pais demuestran que el tipo de interacci\xf3n entre equipos determina el acoplamiento arquitect\xf3nico. Si dos Stream-Aligned Teams colaboran (collaboration mode), la interfaz entre sus bounded contexts ser\xe1 inestable y requerir\xe1 coordinaci\xf3n; si uno consume al otro como X-as-a-Service, la interfaz ser\xe1 un contrato estable con SLA. Esto complementa lo visto en clase sobre Conway's Law y comunicaci\xf3n entre servicios, pero a\xf1ade la dimensi\xf3n de ",(0,i.jsx)(a.strong,{children:"modos de interacci\xf3n"})," como drivers arquitect\xf3nicos que los ADRs y el C4 Model no capturan por s\xed solos."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"4-investigar-qu\xe9-propone-gregor-hohpe-con-la-met\xe1fora-del-architect-elevator-y-c\xf3mo-cambia-la-forma-de-comunicar-decisiones-arquitect\xf3nicas-a-stakeholders",children:'4. [Investigar] \xbfQu\xe9 propone Gregor Hohpe con la met\xe1fora del "Architect Elevator" y c\xf3mo cambia la forma de comunicar decisiones arquitect\xf3nicas a stakeholders?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),": En ",(0,i.jsx)(a.em,{children:"The Software Architect Elevator"}),' (2020), Gregor Hohpe propone que el arquitecto debe funcionar como un "ascensor" que viaja entre el piso de arriba (C-suite, negocio, estrategia) y el piso de abajo (desarrolladores, operaciones, tecnolog\xeda), traduciendo en ambas direcciones sin quedarse atrapado en un solo piso. Esto implica que comunicar una decisi\xf3n arquitect\xf3nica al CFO requiere hablar de ROI, riesgo y time-to-market, no de patrones de dise\xf1o, microservicios o CQRS. Hacia los desarrolladores, requiere traducir la estrategia de negocio en constraints arquitect\xf3nicos accionables.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),': Hohpe sostiene que la mayor\xeda de los arquitectos fallan en la comunicaci\xf3n vertical: o se vuelven "ivory tower architects" (desconectados de la implementaci\xf3n) o "tunel vision architects" (solo ven tecnolog\xeda). Las herramientas de documentaci\xf3n como ADRs y C4 Model resuelven la comunicaci\xf3n horizontal (t\xe9cnica-t\xe9cnica), pero no la vertical (negocio-t\xe9cnica). Esto conecta con lo visto en clase sobre stakeholders y el rol del arquitecto, pero agrega la dimensi\xf3n de traducci\xf3n bidireccional como competencia central, y propone herramientas como los "arc42" para documentaci\xf3n que abarque ambas audiencias.']}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-que-los-adrs-documentan-decisiones-arquitect\xf3nicas-c\xf3mo-se-relaciona-esto-con-el-proceso-de-rfc-request-for-comments-que-usan-empresas-como-spotify-y-c\xf3mo-ambos-se-complementan",children:"5. [Conectar] La clase menciona que los ADRs documentan decisiones arquitect\xf3nicas. \xbfC\xf3mo se relaciona esto con el proceso de RFC (Request for Comments) que usan empresas como Spotify y c\xf3mo ambos se complementan?"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),": Los ADRs (Michael Nygard) documentan el resultado de una decisi\xf3n (contexto, decisi\xf3n, consecuencias), mientras que el proceso RFC (inspirado en el IETF y adoptado por Spotify, Uber y otras) ",(0,i.jsx)(a.strong,{children:"abarca el proceso previo a la decisi\xf3n"}),": alguien escribe un RFC con la propuesta, se somete a revisi\xf3n por pares en un tiempo acotado, se incorpora feedback, y reci\xe9n entonces se toma la decisi\xf3n que se documenta como ADR. Son complementarios: RFC para el debate y construcci\xf3n de consenso, ADR para el registro hist\xf3rico de lo decidido."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": Phil Cal\xe7ado y otros ingenieros de Spotify documentaron su proceso de RFC en su blog de ingenier\xeda (2020). La diferencia fundamental es temporal: el ADR mira hacia atr\xe1s (\xbfqu\xe9 decidimos?), el RFC mira hacia adelante (\xbfqu\xe9 deber\xedamos decidir?). En la clase vimos el formato de ADR, pero no se cubri\xf3 el proceso previo de discusi\xf3n y revisi\xf3n. Un ADR sin RFC puede ser una decisi\xf3n unilateral; un RFC sin ADR pierde trazabilidad. La combinaci\xf3n de ambos \u2014propuesta como RFC, decisi\xf3n como ADR\u2014 es el est\xe1ndar emergente en equipos de plataforma y arquitectura distribuida."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"6-conectar-la-clase-cubre-los-6-atributos-de-calidad-principales-c\xf3mo-los-ampl\xeda-y-estructura-el-est\xe1ndar-isoiec-250102023-respecto-a-lo-visto",children:"6. [Conectar] La clase cubre los 6 atributos de calidad principales. \xbfC\xf3mo los ampl\xeda y estructura el est\xe1ndar ISO/IEC 25010:2023 respecto a lo visto?"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),": El est\xe1ndar ISO/IEC 25010:2023 (evoluci\xf3n del ISO 9126) estructura los atributos de calidad en un modelo jer\xe1rquico con 8 caracter\xedsticas principales y subcaracter\xedsticas medibles. Los 6 vistos en clase (disponibilidad, performance, seguridad, mantenibilidad, escalabilidad, testabilidad) cubren parte del modelo, pero ISO 25010 agrega: ",(0,i.jsx)(a.strong,{children:"Compatibilidad"})," (coexistencia, interoperabilidad), ",(0,i.jsx)(a.strong,{children:"Portabilidad"})," (adaptabilidad, instalabilidad, reemplazabilidad), y ",(0,i.jsx)(a.strong,{children:"Usabilidad"}),' (reconocibilidad, aprendibilidad, operabilidad, protecci\xf3n contra errores de usuario). Adem\xe1s, "disponibilidad" en ISO 25010 es una subcaracter\xedstica de "Reliability" (junto con madurez, tolerancia a fallos y recuperabilidad), y "escalabilidad" no es una caracter\xedstica independiente sino parte de Performance Efficiency.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": El modelo ISO/IEC 25010 es el est\xe1ndar internacional para evaluaci\xf3n de calidad de software. Lo visto en clase es un subconjunto pr\xe1ctico, pero en contextos de compliance (PCI-DSS, HIPAA, SOX) o contratos gubernamentales, los QAs suelen expresarse en t\xe9rminos ISO. Conocer el mapeo entre el framework pragm\xe1tico de la clase y el est\xe1ndar formal permite traducir requisitos de stakeholders regulatorios a decisiones arquitect\xf3nicas concretas."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"7-conectar-en-clase-vimos-que-toda-decisi\xf3n-implica-un-trade-off-c\xf3mo-ayuda-el-modelo-cynefin-dave-snowden-a-tomar-decisiones-arquitect\xf3nicas-en-diferentes-contextos-de-complejidad",children:'7. [Conectar] En clase vimos que "toda decisi\xf3n implica un trade-off". \xbfC\xf3mo ayuda el modelo Cynefin (Dave Snowden) a tomar decisiones arquitect\xf3nicas en diferentes contextos de complejidad?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': El modelo Cynefin clasifica los problemas en cinco dominios: Clear (claro), Complicated (complicado), Complex (complejo), Chaotic (ca\xf3tico) y Disorder (desorden). La clase asume impl\xedcitamente que las decisiones arquitect\xf3nicas est\xe1n en el dominio Complicated (hay una respuesta correcta si se analiza suficiente), pero muchas decisiones modernas est\xe1n en el dominio Complex: causa y efecto solo son visibles en retrospectiva, y la estrategia correcta es "probe-sense-respond" (experimentar, medir, ajustar). Para decisiones en dominio Clear, un ADR con trade-offs es suficiente; para Complex, necesit\xe1s spikes t\xe9cnicos, canary releases y fitness functions.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": Dave Snowden desarroll\xf3 Cynefin en ",(0,i.jsx)(a.em,{children:"Harvard Business Review"})," (2007). Aplicado a arquitectura: migrar de monolito a microservicios es Complex (no hay una respuesta correcta universal), mientras que elegir entre dos proveedores cloud con SLAs comparables es Complicated (se puede analizar y decidir). El modelo ayuda al arquitecto a elegir la estrategia de decisi\xf3n: en Complex no busc\xe1s la respuesta \xf3ptima, busc\xe1s opciones seguras para fallar (safe-to-fail experiments). Esto extiende la noci\xf3n de trade-offs de la clase con una dimensi\xf3n de incertidumbre que los ADRs tradicionales no capturan."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"8-cuestionar-es-el-rol-del-arquitecto-de-software-obsoleto-en-equipos-verdaderamente-\xe1giles-y-aut\xf3nomos-contrast\xe1-la-postura-de-martin-fowler-con-la-de-mary-poppendieck",children:"8. [Cuestionar] \xbfEs el rol del arquitecto de software obsoleto en equipos verdaderamente \xe1giles y aut\xf3nomos? Contrast\xe1 la postura de Martin Fowler con la de Mary Poppendieck."}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': Martin Fowler defiende que el arquitecto evoluciona a un rol de "arquitecto gu\xeda" (no dictador) que establece constraints m\xednimos y deja que el dise\xf1o emerja. Mary Poppendieck, en ',(0,i.jsx)(a.em,{children:"Lean Software Development"}),', va m\xe1s lejos: argumenta que la arquitectura debe ser propiedad colectiva del equipo y que un rol formal de "arquitecto" crea cuellos de botella y desresponsabiliza al equipo. Sin embargo, Fowler responde en su bliki que "architecture is too important to be left to architects alone... but also too important to have no one thinking about it." La postura intermedia (el "arquitecto interno" de ThoughtWorks) es que el rol persiste como facilitador y guardi\xe1n de fitness functions, pero no como tomador de decisiones en solitario.']}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),': Este debate est\xe1 vivo. En Spotify, el modelo de "arquitectura sin arquitectos" mediante Chapters y Guilds intenta distribuir la responsabilidad. En Amazon, el rol de "Principal Engineer" act\xfaa como arquitecto distribuido. La evidencia de ThoughtWorks Tech Radar sugiere que el rol sobrevive pero muta: de "tomador de decisiones" a "dise\xf1ador de constraints y habilitador de equipos". La pregunta no es si el rol existe, sino si est\xe1 concentrado o distribuido.']}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"9-cuestionar-el-principio-de-la-revisarltima-decisi\xf3n-responsable-last-responsible-moment-es-peligroso-en-sistemas-cr\xedticos-de-seguridad-avi\xf3nica-dispositivos-m\xe9dicos-contrast\xe1-con-la-postura-de-nancy-leveson",children:'9. [Cuestionar] \xbfEl principio de la "Revisarltima Decisi\xf3n Responsable" (Last Responsible Moment) es peligroso en sistemas cr\xedticos de seguridad (avi\xf3nica, dispositivos m\xe9dicos)? Contrast\xe1 con la postura de Nancy Leveson.'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),": S\xed, es peligroso si se aplica indiscriminadamente. Nancy Leveson, en ",(0,i.jsx)(a.em,{children:"Engineering a Safer World"}),' (MIT Press, 2011), argumenta que en sistemas safety-critical, muchas decisiones arquitect\xf3nicas deben tomarse temprano porque son prerequisito de los an\xe1lisis de seguridad (STPA/STAMP). Diferir la decisi\xf3n de redundancia de hardware en un marcapasos hasta el "\xfaltimo momento responsable" puede significar que ya no hay tiempo para certificar el dise\xf1o con la FDA. El principio del Last Responsible Moment, originado en ',(0,i.jsx)(a.em,{children:"Lean Software Development"})," de Poppendieck, asume que el costo de cambio es bajo \u2014supuesto falso en sistemas con certificaci\xf3n regulatoria y hardware."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),": El debate es contextual. Para un SaaS con deploy continuo, diferir es racional. Para un sistema con ISO 26262 (automotriz) o DO-178C (avi\xf3nica), diferir es negligencia. La clase no cubri\xf3 esta distinci\xf3n de dominio, que es cr\xedtica: los arquitectos deben calibrar el principio seg\xfan la criticidad del sistema. Capers Jones document\xf3 que el costo de cambio crece exponencialmente en sistemas regulados, no linealmente como en software empresarial."]}),"\n",(0,i.jsx)(a.hr,{}),"\n",(0,i.jsx)(a.h3,{id:"10-cuestionar-deber\xedan-los-atributos-de-calidad-ser-definidos-top-down-por-el-arquitecto-o-emerger-de-los-equipos-qu\xe9-dice-el-manifiesto-\xe1gil-y-c\xf3mo-lo-rebate-el-sei",children:'10. [Cuestionar] \xbfDeber\xedan los atributos de calidad ser definidos "top-down" por el arquitecto o emerger de los equipos? \xbfQu\xe9 dice el manifiesto \xe1gil y c\xf3mo lo rebate el SEI?'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Respuesta"}),': El Manifiesto \xc1gil valora "individuos e interacciones sobre procesos y herramientas" y "responder al cambio sobre seguir un plan", lo que sugiere que los QAs deber\xedan emerger. El SEI (Software Engineering Institute), creador de ATAM, argumenta que los QAs cr\xedticos (seguridad, disponibilidad) no "emergen" \u2014deben ser dise\xf1ados expl\xedcitamente porque no son visibles para el usuario hasta que fallan. La postura intermedia de Bass, Clements y Kazman en ',(0,i.jsx)(a.em,{children:"Software Architecture in Practice"})," es: los QAs deben ser elicitados colaborativamente (arquitecto + stakeholders + equipo) pero verificados formalmente con escenarios de calidad y fitness functions."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Por qu\xe9"}),': Este es un falso dilema. Los QAs no son "top-down" ni "bottom-up": son "outside-in". El usuario final define el QA (necesito que el sistema est\xe9 disponible 99.9%), el arquitecto traduce eso en t\xe1cticas (redundancia, circuit breaker) y el equipo implementa. El error es ambos extremos: arquitectos definiendo QAs sin consultar al negocio (sobre-ingenier\xeda) o equipos ignorando QAs hasta que el sistema falla en producci\xf3n (deuda t\xe9cnica por omisi\xf3n). La clase mencion\xf3 trade-offs pero no este debate sobre ownership de los QAs.']}),"\n",(0,i.jsx)(a.hr,{})]})}function u(e={}){const{wrapper:a}={...(0,n.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,a,o){o.d(a,{R:()=>r,x:()=>t});var s=o(96540);const i={},n=s.createContext(i);function r(e){const a=s.useContext(n);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),s.createElement(n.Provider,{value:a},e.children)}}}]);